INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 319, 10, 20001, 0, 2, 0, "", "", 0, 24016);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (20, 320, 10, 20001, 0, 2, 0, "", "", 0, 23001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 321, 1, 40011, 1, 2, 125801, "リリ", "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 0, 24001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 322, 2, 40011, 1, 2, 126001, "クリア", "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 0, 24001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 323, 3, 40011, 1, 2, 126101, "プレシア", "んーと。\nこれ、あげる。\nはい", 0, 24001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 324, 4, 40011, 2, 2, 125801, "リリ", "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 0, 24001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 325, 5, 40011, 2, 2, 126001, "クリア", "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 0, 24001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (1, 326, 6, 40011, 2, 2, 126101, "プレシア", "お兄。\nきてくれて、うれしい", 0, 24001);
INSERT INTO `v1_81a2cf0ca8fa94acb428ab0afa61f3b7133f85d1edcad4a7efb76ea75e3b14b6` VALUES (100, 327, 1, 80009, 0, 8, 0, "", "", 532001, 91002);
